/**
 * A user's avatar: a picture generated by Boring Avatars (MIT,
 * https://boringavatars.com) from a seed, in one of six styles and one of
 * the house palettes, or a photo from the sign-in provider.
 *
 * The choice lives in `profiles.avatar_url` so no new column is needed:
 *   - null                       the default picture, seeded by the user id
 *   - "boring:<style>:<palette>:<seed>"   a picture the user chose
 *   - an http(s) URL              a photo (the sign-up trigger stores the
 *                                 Google picture there)
 * The same seed, style and palette always draw the same picture, so the
 * value is all that needs saving. No server code or browser code is needed
 * here; both sides import it.
 */

export const AVATAR_VARIANTS = ["beam", "marble", "pixel", "sunset", "ring", "bauhaus"] as const;
export type AvatarVariant = (typeof AVATAR_VARIANTS)[number];

/** Five colours each, picked to read on the light and the dark glass. */
export const AVATAR_PALETTES = {
  eain: ["#f4506e", "#ffb3c1", "#ffe4e8", "#7a2e45", "#ffd166"],
  garden: ["#2f6b4f", "#9bd4a6", "#e7f3d8", "#f2c14e", "#d95d39"],
  sea: ["#0b3954", "#087e8b", "#bfd7ea", "#ff5a5f", "#f7f7ff"],
  ember: ["#5c2a9d", "#e94f8a", "#ff9f68", "#ffd27f", "#2b1d4a"],
  dusk: ["#1f2937", "#6b7280", "#d1d5db", "#f9fafb", "#f4506e"],
} as const;
export type AvatarPalette = keyof typeof AVATAR_PALETTES;
export const AVATAR_PALETTE_NAMES = Object.keys(AVATAR_PALETTES) as AvatarPalette[];

export const DEFAULT_VARIANT: AvatarVariant = "beam";
export const DEFAULT_PALETTE: AvatarPalette = "eain";

/** Seeds are short and plain so the stored value stays readable. */
export const SEED_PATTERN = /^[a-z0-9-]{1,64}$/;

export type GeneratedAvatar = {
  kind: "generated";
  variant: AvatarVariant;
  palette: AvatarPalette;
  seed: string;
};
export type PhotoAvatar = { kind: "photo"; src: string };
export type Avatar = GeneratedAvatar | PhotoAvatar;

const PREFIX = "boring:";

export function isAvatarVariant(value: unknown): value is AvatarVariant {
  return typeof value === "string" && (AVATAR_VARIANTS as readonly string[]).includes(value);
}

export function isAvatarPalette(value: unknown): value is AvatarPalette {
  return typeof value === "string" && value in AVATAR_PALETTES;
}

/** The stored form of a generated avatar. */
export function serializeAvatar(avatar: GeneratedAvatar): string {
  return `${PREFIX}${avatar.variant}:${avatar.palette}:${avatar.seed}`;
}

/** Reads a stored generated avatar; null for anything else, including junk. */
export function parseGeneratedAvatar(value: string | null | undefined): GeneratedAvatar | null {
  if (!value || !value.startsWith(PREFIX)) return null;
  const [variant, palette, seed, extra] = value.slice(PREFIX.length).split(":");
  if (extra !== undefined || !isAvatarVariant(variant) || !isAvatarPalette(palette)) return null;
  if (!seed || !SEED_PATTERN.test(seed)) return null;
  return { kind: "generated", variant, palette, seed };
}

/**
 * What to draw for a profile. The user id seeds the default so the picture
 * stays the same when the name changes. Photo URLs must be https; anything
 * else falls back to the default picture.
 */
export function resolveAvatar(value: string | null | undefined, userId: string): Avatar {
  const generated = parseGeneratedAvatar(value);
  if (generated) return generated;
  if (value && /^https:\/\//.test(value)) return { kind: "photo", src: value };
  return { kind: "generated", variant: DEFAULT_VARIANT, palette: DEFAULT_PALETTE, seed: userId };
}

/** A fresh seed, eight characters from the alphabet the pattern allows. */
export function randomSeed(): string {
  const alphabet = "abcdefghijklmnopqrstuvwxyz0123456789";
  const bytes = new Uint8Array(8);
  crypto.getRandomValues(bytes);
  return Array.from(bytes, (b) => alphabet[b % alphabet.length]).join("");
}
